-- Dados oficiais do Quest Tracker (gerado por scripts/build-quest-sql.mjs a partir de quests_live.csv e exp_table.csv).
-- 382 quests, 40 categorias novas e a tabela de EXP dos levels 1 a 120 (modo "acumulada no início do level").
-- Rode DEPOIS do 30 e do 31. É seguro rodar de novo, mas isso volta as quests ao texto original (apaga edições feitas no painel).

-- 1) Remove os DADOS FICTÍCIOS do arquivo 32 (se foram carregados): quests TESTE-nnn e levels acima de 120 que não existem no jogo.
delete from public.quests where id like 'TESTE-%';
delete from public.exp_levels where level > 120;

-- 2) Categorias (as 5 padrão continuam; estas são o "grupo do livro de quests" do jogo)
on conflict (id) do update set name = excluded.name, sort = excluded.sort;

-- 3) Tabela de EXP: o valor do level L é o EXP total ao chegar no level L (level 1 = 0). Sem extrapolar além do level 120.
on conflict (level) do update set value = excluded.value, active = true;
update public.quest_settings set exp_table_mode = 'cumulative_start' where id = 1;

-- 4) Quests. EXP 0 é um valor real (a quest não dá EXP). Campo vazio no arquivo continua vazio (nada foi chutado).
on conflict (id) do update set name = excluded.name, category_id = excluded.category_id, min_level = excluded.min_level, max_level = excluded.max_level,
  map = excluded.map, npc = excluded.npc, description = excluded.description, objectives = excluded.objectives, base_exp = excluded.base_exp,
  prerequisites = excluded.prerequisites, repeat_type = excluded.repeat_type, repeat_interval_hours = excluded.repeat_interval_hours, active = excluded.active, archived = false;
